_notesproxy_completions_node_flag_state() {
  case "$1:$2" in
    2:-l|2:--location) return 2 ;;
    2:-e|2:--editor) return 2 ;;
    2:-c|2:--category) return 2 ;;
    2:-a|2:--autoopen) return 2 ;;
    5:-l|5:--location) return 2 ;;
    5:-e|5:--editor) return 2 ;;
    5:-c|5:--category) return 2 ;;
    5:-a|5:--autoopen) return 2 ;;
    6:-e|6:--editor) return 2 ;;
    9:-l|9:--location) return 2 ;;
    9:-e|9:--editor) return 2 ;;
    9:-c|9:--category) return 2 ;;
    9:-a|9:--autoopen) return 2 ;;
  esac

  return 1
}

_notesproxy_completions_option_seen() {
  local completed_option option_name
  for completed_option in "${completed_options[@]}"; do
    for option_name in "$@"; do
      [[ "$completed_option" == "$option_name" ]] && return 0
    done
  done

  return 1
}

_notesproxy_completions_resolve_node() {
  node_id=0
  node_word_count=0
  positional_index=0

  local word
  for word in "${non_options[@]}"; do
    case "$node_id:$word" in
      0:note)
        node_id=1
        node_word_count=1
        ;;
      0:n)
        node_id=1
        node_word_count=1
        ;;
      0:config)
        node_id=8
        node_word_count=1
        ;;
      0:c)
        node_id=8
        node_word_count=1
        ;;
      0:interactive)
        node_id=11
        node_word_count=1
        ;;
      0:i)
        node_id=11
