        ;;
      1:d)
        node_id=3
        node_word_count=2
        ;;
      1:list)
        node_id=4
        node_word_count=2
        ;;
      1:ls)
        node_id=4
        node_word_count=2
        ;;
      1:edit)
        node_id=5
