        ;;
      1:nuke)
        node_id=7
        node_word_count=2
        ;;
      1:n)
        node_id=7
        node_word_count=2
        ;;
      8:edit)
        node_id=9
        node_word_count=2
        ;;
      8:e)
        node_id=9
        node_word_count=2
        ;;
      8:list)
        node_id=10
        node_word_count=2
        ;;
      8:ls)
        node_id=10
        node_word_count=2
        ;;
      *)
        break
        ;;
    esac
  done

  positional_index=$((${#non_options[@]} - node_word_count))
}

_notesproxy_completions() {
