      return
      ;;
    9:-a|9:--autoopen)
      while read -r; do COMPREPLY+=("$REPLY"); done < <(compgen -W "true false" -- "$cur")
      return
      ;;
  esac

  if [[ "${cur:0:1}" != "-" ]] && (( positional_index == 0 )); then
    case "$node_id" in
